pub open spec fn valid<T>(temp_pred: TempPred<T>) -> bool {
    forall |ex: Execution<T>| temp_pred.satisfied_by(ex)
}


// File: rules.rs
	#[verifier::external_body]
proof fn always_unfold<T>(ex: Execution<T>, p: TempPred<T>)
    requires always(p).satisfied_by(ex),
    ensures forall |i: nat| p.satisfied_by(#[trigger] ex.suffix(i)),
	{
		unimplemented!()
	}

proof fn always_and_split<T>(ex: Execution<T>, p: TempPred<T>, q: TempPred<T>)
    requires always(p.and(q)).satisfied_by(ex)
    ensures always(p).satisfied_by(ex) && always(q).satisfied_by(ex)
{
    // Unfold `always(p.and(q))` into a statement about every suffix.
    always_unfold(ex, p.and(q));

    // From `forall i. (p.and(q)).satisfied_by(ex.suffix(i))`, we get `forall i. p.satisfied_by(ex.suffix(i))`.
    assert(always(p).satisfied_by(ex));
    assert(always(q).satisfied_by(ex));
}


proof fn always_distributed_by_and<T>(p: TempPred<T>, q: TempPred<T>)
    ensures valid(always(p.and(q)).implies(always(p).and(always(q)))),
{
    // Unfold `valid` to show the implication holds for every execution.
    assert(valid(always(p.and(q)).implies(always(p).and(always(q)))));
}


