proof fn always_and_split<T>(ex: Execution<T>, p: TempPred<T>, q: TempPred<T>)
    requires always(p.and(q)).satisfied_by(ex)
    ensures always(p).satisfied_by(ex) && always(q).satisfied_by(ex)
{
    // Unfold `always(p.and(q)).satisfied_by(ex)` to get satisfaction on all suffixes.
    always_unfold(ex, p.and(q));

    // Unfold the definitions of `always(p)` and `always(q)`.
    // We must show:
    //   forall i. p.satisfied_by(ex.suffix(i))
    //   forall i. q.satisfied_by(ex.suffix(i))
    // which follows because (p.and(q)).satisfied_by(...) is a conjunction.
    assert(forall |i: nat| p.satisfied_by(ex.suffix(i))) by {
        reveal(always(p.and(q)));
        // After `always_unfold`, `p.and(q)` holds on every suffix.
        assert((p.and(q)).satisfied_by(ex.suffix(i)));
    };

    assert(forall |i: nat| q.satisfied_by(ex.suffix(i))) by {
        reveal(always(p.and(q)));
        assert((p.and(q)).satisfied_by(ex.suffix(i)));
    };

    assert(always(p).satisfied_by(ex));
    assert(always(q).satisfied_by(ex));
}


