}) by {
    // Since `always_and_split` is a proof function, call it under the antecedent
    // using a conditional statement.
    forall |ex: Execution<T>| {
        if always(p.and(q)).satisfied_by(ex) {
            always_and_split(ex, p, q);
        }
    };
    // The goal is the universally quantified implication; the conditional reasoning above discharges it.
    assert(forall |ex: Execution<T>| {
        always(p.and(q)).satisfied_by(ex) ==> (always(p).and(always(q))).satisfied_by(ex)
    });
};

